  ('tradition-talent-s3','QUESTION_ANSWER',27,$q$Explain with context and significance: “Tradition cannot be inherited, and if you want it you must obtain it by great labour.”$q$,$q$“Tradition cannot be inherited, and if you want it you must obtain it by great labour.” — উদ্ধৃতিটির ব্যাখ্যা, প্রেক্ষাপট ও তাৎপর্য লিখুন।$q$,NULL,NULL),
  ('tradition-talent-s3','QUESTION_ANSWER',28,$q$Explain with context and significance: “The historical sense involves a perception, not only of the pastness of the past, but of its presence.”$q$,$q$“The historical sense involves a perception, not only of the pastness of the past, but of its presence.” — উদ্ধৃতিটির ব্যাখ্যা, প্রেক্ষাপট ও তাৎপর্য লিখুন।$q$,NULL,NULL),
  ('tradition-talent-s3','QUESTION_ANSWER',29,$q$Explain with context and significance: “No poet, no artist of any art, has his complete meaning alone.”$q$,$q$“No poet, no artist of any art, has his complete meaning alone.” — উদ্ধৃতিটির ব্যাখ্যা, প্রেক্ষাপট ও তাৎপর্য লিখুন।$q$,NULL,NULL),
  ('tradition-talent-s3','QUESTION_ANSWER',30,$q$Explain with context and significance: “The past should be altered by the present as much as the present is directed by the past.”$q$,$q$“The past should be altered by the present as much as the present is directed by the past.” — উদ্ধৃতিটির ব্যাখ্যা, প্রেক্ষাপট ও তাৎপর্য লিখুন।$q$,NULL,NULL),
  ('tradition-talent-s3','QUESTION_ANSWER',31,$q$Explain with context and significance: “Honest criticism and sensitive appreciation is directed not upon the poet but upon the poetry.”$q$,$q$“Honest criticism and sensitive appreciation is directed not upon the poet but upon the poetry.” — উদ্ধৃতিটির ব্যাখ্যা, প্রেক্ষাপট ও তাৎপর্য লিখুন।$q$,NULL,NULL),
  ('tradition-talent-s3','QUESTION_ANSWER',32,$q$Explain with context and significance: “The progress of an artist is a continual self-sacrifice, a continual extinction of personality.”$q$,$q$“The progress of an artist is a continual self-sacrifice, a continual extinction of personality.” — উদ্ধৃতিটির ব্যাখ্যা, প্রেক্ষাপট ও তাৎপর্য লিখুন।$q$,NULL,NULL),
  ('tradition-talent-s3','QUESTION_ANSWER',33,$q$Explain with context and significance: “Poetry is not a turning loose of emotion, but an escape from emotion.”$q$,$q$“Poetry is not a turning loose of emotion, but an escape from emotion.” — উদ্ধৃতিটির ব্যাখ্যা, প্রেক্ষাপট ও তাৎপর্য লিখুন।$q$,NULL,NULL),
  ('tradition-talent-s3','QUESTION_ANSWER',34,$q$Explain with context and significance: “It is not the expression of personality, but an escape from personality.”$q$,$q$“It is not the expression of personality, but an escape from personality.” — উদ্ধৃতিটির ব্যাখ্যা, প্রেক্ষাপট ও তাৎপর্য লিখুন।$q$,NULL,NULL),
  ('tradition-talent-s3','QUESTION_ANSWER',35,$q$Explain with context and significance: “The mind of the poet is the shred of platinum.”$q$,$q$“The mind of the poet is the shred of platinum.” — উদ্ধৃতিটির ব্যাখ্যা, প্রেক্ষাপট ও তাৎপর্য লিখুন।$q$,NULL,NULL)
